/// <summary><c>SendBase</c> (veja a referência da API).</summary>
public class SendBase : BzapperObject
{
    /// <summary><c>instance_id</c> — OPTIONAL. Only `to` is required. Omit `instance_id` to let the gateway auto-pick a number from your pool (rotation + conversation affinity) — the recommended path. Provide it ONLY to FORCE the send from a specific number. Get ids from `GET /instances`.</summary>
    [JsonPropertyName("instance_id")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? InstanceId { get; set; }

    /// <summary><c>pool_id</c> — Rotates within this pool (when instance_id is omitted).</summary>
    [JsonPropertyName("pool_id")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? PoolId { get; set; }

    /// <summary><c>sticky</c> — Conversation affinity (support): without instance_id/pool_id, it AUTOMATICALLY reuses the number that already talks to `to`, ensuring the whole interaction stays on the same number. Default **true**; send **false** to force rotation (e.g. campaign/broadcast).</summary>
    [JsonPropertyName("sticky")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Sticky { get; set; }

    /// <summary><c>to</c> — Destination: E.164 phone (+DDIdigits), contact JID (…@s.whatsapp.net), group JID (…@g.us) or the contact's @lid. A @lid is translated to the phone when the connected number knows it; the official rail accepts phone only. Obrigatório.</summary>
    [JsonPropertyName("to")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? To { get; set; }

    /// <summary><c>quoted_message_id</c> — Quoted wa_message_id (reply).</summary>
    [JsonPropertyName("quoted_message_id")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? QuotedMessageId { get; set; }

    /// <summary><c>quoted_participant</c> — Author (phone or JID) of the quoted/reacted message. Only needed in groups when the quoted message is not in bZapper history — otherwise it is resolved automatically.</summary>
    [JsonPropertyName("quoted_participant")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? QuotedParticipant { get; set; }

    /// <summary><c>client_reference</c> — Client end-to-end correlation.</summary>
    [JsonPropertyName("client_reference")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ClientReference { get; set; }

    /// <summary><c>mentions</c> — Mentioned people (group): phones ("5511…", "+55 11 9…") or JIDs. The body must contain "@&lt;digits&gt;" for the mention to be highlighted.</summary>
    [JsonPropertyName("mentions")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? Mentions { get; set; }

    /// <summary><c>scheduled_at</c> — OPTIONAL. Schedule the send for a future RFC3339 timestamp. The gateway holds the message and dispatches it at that exact time (the number is picked at send time). Max lead time by plan: Free 24h, Pro 30 days, and up to 1 year with the "Extended scheduling" add-on. Returns status `scheduled` with a `scheduled_id`. OTP cannot be scheduled.</summary>
    [JsonPropertyName("scheduled_at")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonConverter(typeof(UtcDateTimeConverter))]
    public DateTimeOffset? ScheduledAt { get; set; }

    /// <summary><c>groups</c> — OPTIONAL. Contact-group keys to correlate/stamp onto the recipient contact when this send resolves (see `GET /contact-groups`). Does not send the message to a WhatsApp group.</summary>
    [JsonPropertyName("groups")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? Groups { get; set; }

    /// <summary><c>tags</c> — OPTIONAL. Tag keys to correlate/stamp onto the recipient contact when this send resolves (see `GET /tags`).</summary>
    [JsonPropertyName("tags")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? Tags { get; set; }

    /// <summary><c>force</c> — OPTIONAL. When true, bypasses an inferred suppression (e.g. opt-out inferred from behaviour) for this send. Does NOT override an explicit suppression entry (`/suppressions`) — use with care and only with a lawful basis.</summary>
    [JsonPropertyName("force")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Force { get; set; }
}

